update t_cx_specify_machine
sap_code = #{sapCode}, embryo_code = #{embryoCode}, machine_code = #{machineCode}, line_type = #{lineType}, job_type = #{jobType}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, remark = #{remark},
where id = #{id}

